exec('"""Finite six-run orchestration helpers. No automatic retries or old-run writes."""\nimport hashlib,json,os,time,subprocess\nfrom pathlib import Path\nNAME=\'MLR_IFA_ALIGN_RANDOM_OBJECT_GOAL41_42_43_20261110_v2\'\nQ=Path(\'/data/mlr_ifa/experiment_workspaces\')/NAME\nP=Path(\'/data/mlr_ifa/experiments\')/NAME\nPY=\'/data/mlr_ifa/env/bin/python\'\nOLD=Q.parent/\'S_Q1_OBJECT_GOAL41_42_43_20261109_rerun_v1\'\nOLD_HASH=\'fbbce2917380d1cde1025f0006b6fdd6bc7959f92226bb5588cc431ee0c8d96c\'\nCASES=[s+\'_\'+str(i) for s in [\'OBJECT\',\'GOAL\'] for i in [41,42,43]]\ndef js(p):return json.loads(Path(p).read_text())\ndef sha(p):\n h=hashlib.sha256()\n with open(p,\'rb\') as f:\n  for b in iter(lambda:f.read(1024**2),b\'\'):h.update(b)\n return h.hexdigest()\ndef write(p,x):\n p=Path(p);tmp=p.with_suffix(\'.tmp\');tmp.write_text(json.dumps(x,indent=2)+\'\\n\');os.replace(tmp,p)\ndef event(kind,**kw):\n with (Q/\'EVENTS.jsonl\').open(\'a\') as f:f.write(json.dumps(dict(kind=kind,time=time.time(),**kw))+\'\\n\');f.flush();os.fsync(f.fileno())\ndef processes(roots):\n out=[]\n for p in Path(\'/proc\').glob(\'[0-9]*\'):\n  try:\n   if int(p.name)==os.getpid():continue\n   cmd=(p/\'cmdline\').read_bytes().replace(b\'\\0\',b\' \').decode(errors=\'replace\')\n   env=(p/\'environ\').read_bytes().replace(b\'\\0\',b\' \').decode(errors=\'replace\')\n   if any(str(r) in cmd or str(r) in env for r in roots):out.append(dict(pid=int(p.name),cmd=cmd,state=(p/\'stat\').read_text().split(\')\')[-1].split()[0]))\n  except (OSError,ProcessLookupError):pass\n return out\ndef verify():\n c=js(Q/\'CONTRACT.json\')\n for rel,h in c[\'code_files\'].items():assert sha(Q/rel)==h,rel\n for rel,h in c[\'private_files\'].items():assert sha(P/rel)==h,rel\n return c\ndef previous_finished():\n assert sha(OLD/\'CONTRACT.json\')==OLD_HASH\n assert all(sha(path)==h for path,h in js(OLD/\'CONTRACT.json\')[\'files\'].items())\n eng=OLD/\'engineering_reboot_resume_20261109_v1\'\n assert sha(eng/\'CONTRACT.json\')==\'9c5b7e0b23e1beabb4bf28216f6a75f372d6d2f68b3f6515c27debdd8eda34bb\'\n assert all(sha(path)==h for path,h in js(eng/\'CONTRACT.json\')[\'files\'].items())\n assert not (OLD/\'controller.exit\').exists()\n assert (eng/\'controller.exit\').read_text().strip()==\'0\'\n roots=[OLD]\n for suite in [\'OBJECT\',\'GOAL\']:\n  root=OLD.parent/(\'S_Q1_\'+suite+\'41_42_43_20261109_rerun_v1\');roots.append(root)\n  exit_path=eng/\'OBJECT_controller.exit\' if suite==\'OBJECT\' else root/\'controller.exit\'\n  if suite==\'OBJECT\':assert not (root/\'controller.exit\').exists()\n  assert exit_path.read_text().strip()==\'0\'\n  assert js(root/\'Q1_EVALUATION_COMPLETE.json\')[\'episodes\']==600\n  for seed in [41,42,43]:\n   d=root/(\'Q1_\'+str(seed))\n   train_exit=eng/(\'Q1_\'+str(seed)+\'_train.exit\') if suite==\'OBJECT\' and seed in [41,42] else d/\'train_S.exit\'\n   assert train_exit.read_text().strip()==\'0\' and (d/\'evaluate.exit\').read_text().strip()==\'0\'\n   assert len(js(d/\'EPOCHS_S.json\'))==400 and len(js(d/\'OUTCOMES.json\'))==200\n assert not processes(roots),\'Current q=1 still active; never interrupt it\'\n failed=Q.parent/\'MLR_IFA_ALIGN_RANDOM_OBJECT_GOAL41_42_43_20261109_v1\'\n failed_private=P.parent/failed.name\n assert sha(failed/\'CONTRACT.json\')==\'db88ef7991d4cfd6e77b6897977779ed5d37a85682cd63c14441bb63bddcd7c3\'\n assert (failed/\'controller.exit\').read_text().strip()==\'1\'\n assert sha(failed/\'FAILURE.json\')==\'9457a2c32359c38ade6b5811633eb447f9647b7e8070ea739399779978e48c82\'\n assert not processes([failed,failed_private])\n config=Path(\'/data/mlr_ifa/config/config_adaptation.yaml\')\n assert sha(config)==\'44ee53d32cdb509569ca7fb6b2674ce81f51deb95908e9abde093ff3677f72bf\'\n\ndef acceptance_gate():\n previous_finished();a=js(Q/\'POST_Q1_ACCEPTANCE.json\')\n assert a[\'status\']==\'PASS_BOTH_Q1_SUITES_ACCEPTED_AND_PUBLISHED\'\n assert a[\'global_contract\']==OLD_HASH and a[\'global_root\']==str(OLD)\n for suite in [\'OBJECT\',\'GOAL\']:\n  row=a[\'suites\'][suite];assert row[\'audit\'][\'status\']==\'PASS_COMPLETE_LOCAL_ACCEPTANCE\'\n  assert row[\'audit\'][\'contract\']==sha(OLD.parent/(\'S_Q1_\'+suite+\'41_42_43_20261109_rerun_v1\')/\'CONTRACT.json\')\n  assert row[\'audit\'][\'formal_episodes\']==600 and row[\'audit\'][\'epochs\']==1200\n  assert hashlib.sha256(row[\'audit_text\'].encode()).hexdigest()==row[\'audit_sha256\']\n  assert json.loads(row[\'audit_text\'])==row[\'audit\']\n  assert row[\'publication_path\'] in a[\'published_files\']\n  assert a[\'published_files\'][row[\'publication_path\']][\'sha256\']==row[\'audit_sha256\']\n assert len(a[\'remote_commit\'])==40\ndef capacity():\n allocated=0;seen=set()\n if P.exists():\n  for p in P.rglob(\'*\'):\n   if not p.is_file() or p.is_symlink():continue\n   st=p.stat();key=(st.st_dev,st.st_ino)\n   if key not in seen:seen.add(key);allocated+=st.st_blocks*512\n result={}\n for mount,bound,reserve in [(\'/data\',6*1024**3,2*1024**3),(\'/root\',128*1024**2,1024**3)]:\n  s=os.statvfs(mount);free=s.f_bavail*s.f_frsize;remaining=max(0,bound-allocated) if mount==\'/data\' else bound\n  result[mount]=dict(free=free,remaining=remaining,reserve=reserve,spare=free-remaining-reserve)\n  assert free-remaining>=reserve,(\'Fresh capacity insufficient; no deletion or paid expansion\',result)\n return result\ndef env(case):\n e=os.environ.copy();e.update(CORESET_OUT=str(P/case),CORESET_SEED=case[-2:],PYTHONPATH=str(Q/\'cases\'/case/\'source\'),PYTHONDONTWRITEBYTECODE=\'1\',TOKENIZERS_PARALLELISM=\'false\',HF_HUB_OFFLINE=\'1\',TRANSFORMERS_OFFLINE=\'1\',CUDA_VISIBLE_DEVICES=\'0\',LIBERO_CONFIG_PATH=\'/data/mlr_ifa/config\',HF_HOME=\'/data/mlr_ifa/cache/huggingface\',MUJOCO_GL=\'egl\',MPLBACKEND=\'Agg\',OMP_NUM_THREADS=\'1\',MKL_NUM_THREADS=\'1\',OPENBLAS_NUM_THREADS=\'1\')\n return e\n')
previous_finished()
assert not Q.exists() and not P.exists()
results={}
failed=Q.parent/'MLR_IFA_ALIGN_RANDOM_OBJECT_GOAL41_42_43_20261109_v1'
for case in CASES:
 e=env(case);e['CORESET_OUT']=str(P.parent/failed.name/case);e['PYTHONPATH']=str(failed/'cases'/case/'source');e['CUDA_VISIBLE_DEVICES']=''
 code="import importlib; importlib.import_module('coreset_exp.train'); importlib.import_module('coreset_exp.evaluate'); print('IMPORT_ONLY_PASS_NO_MAIN')"
 p=subprocess.run([PY,'-B','-c',code],env=e,cwd=failed/'cases'/case/'source',capture_output=True,text=True)
 assert p.returncode==0,(case,p.stderr[-4000:]);assert 'IMPORT_ONLY_PASS_NO_MAIN' in p.stdout
 results[case]=dict(exit=0,status='PASS_TRAIN_AND_EVALUATOR_IMPORT_WITHOUT_MAIN',stdout_sha256=hashlib.sha256(p.stdout.encode()).hexdigest())
